Now let's complete the loop by connecting a sensor input directly to a physical output actuator!

### Hardware Mission: Proximity Alarm LED
Keep your HC-SR04 ultrasonic sensor wired on pins `9` (TRIG) and `10` (ECHO). Add an indicator LED:
- Connect the **Anode** (longer leg) of a Red LED to Uno Digital Pin **13** (which has an onboard series resistor).
- Connect the **Cathode** (shorter flat leg) of the LED to the **GND** rail.

### Firmware Architecture:
Here is how sensor readings drive output decisions:

```cpp
const int trigPin = 9;
const int echoPin = 10;
const int alertLedPin = 13;
const int NEAR_THRESHOLD_CM = 15; // Trigger alarm if closer than 15 cm

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(alertLedPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // Ping ultrasonic sensor
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  long duration = pulseIn(echoPin, HIGH);
  int distanceCm = duration * 0.034 / 2;

  // Threshold decision logic
  if (distanceCm > 0 && distanceCm < NEAR_THRESHOLD_CM) {
    digitalWrite(alertLedPin, HIGH); // Alarm ON: Monster eye glows!
    Serial.println("WARNING: Intruder in perimeter!");
  } else {
    digitalWrite(alertLedPin, LOW);  // Alarm OFF: Area clear
    Serial.println("Status: Patrol normal.");
  }

  delay(100);
}
```

Upload the sketch, wave your hand in front of the sensor, and observe how your monster instantly reacts to proximity!

### Hardware Build: Ultrasonic Intruder Sentry

Connect your HC-SR04 distance sensor and an alert LED:
- Trig -> Pin 9, Echo -> Pin 10
- LED Anode -> Pin 13 through a 220Ω resistor, Cathode -> GND

```cpp
const int trigPin = 9;
const int echoPin = 10;
const int ledPin = 13;
const int alertThresholdCm = 15; // 15 cm threshold

void setup() {
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  long duration = pulseIn(echoPin, HIGH);
  float distanceCm = (duration * 0.0343) / 2.0;

  if (distanceCm > 0 && distanceCm < alertThresholdCm) {
    digitalWrite(ledPin, HIGH); // Intruder detected!
  } else {
    digitalWrite(ledPin, LOW);  // All clear
  }
  delay(100);
}
```

